pragma solidity >=0.8.0;

contract UncheckedConstDiv {
    int16 public folded;
    uint256 public count;

    function uncheckedDiv() external returns (int16) {
        unchecked {
            int16 x = type(int16).min / int16(-1);
            folded = x;
            count += 1;
            return x;
        }
    }
}
